from collections import deque

def flood_fill_to_edges(grid, start_color, start_pos):
    """Returns True if the start position can reach the edge via start_color"""
    h, w = len(grid), len(grid[0])
    if not (0 <= start_pos[0] < h and 0 <= start_pos[1] < w):
        return False
    q = deque([start_pos])
    visited = set([start_pos])

    while q:
        r, c = q.popleft()
        # Check if this position is on or adjacent to edge
        if r == 0 or r == h - 1 or c == 0 or c == w - 1:
            return True
        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == start_color and (nr, nc) not in visited:
                visited.add((nr, nc))
                q.append((nr, nc))
    return False

