def apply_rule(grid, fill_color):
    """Apply the rule: fill_color cells that can't reach edge turn to 4"""
    h, w = len(grid), len(grid[0])
    output = [row[:] for row in grid]

    for r in range(h):
        for c in range(w):
            if grid[r][c] == fill_color:
                if not flood_fill_to_edges(grid, fill_color, (r, c)):
                    output[r][c] = 4
    return output

